<div><label for="cf-city">Property location</label><select id="cf-city" name="city"><option>Detroit</option><option>Grand Rapids</option><option>Ann Arbor</option><option>Lansing</option><option>Flint</option><option>Dearborn</option><option>Troy</option><option>Sterling Heights</option><option>Kalamazoo</option><option>Saginaw</option><option>Traverse City</option><option>Marquette</option><option>Elsewhere in Michigan</option></select></div>
